def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = np.full_like(g, bg)
    emit(out.copy(), "Clear all objects, leaving only the background; each part will be restamped shifted.")
    groups = components(g != bg)
    for cells in groups:
        cols = {}
        for (y, x) in cells:
            cols.setdefault(int(g[y, x]), []).append((y, x))
        # order colours by topmost row: top part moves left, lower part(s) move right
        order = sorted(cols, key=lambda c: min(y for y, _ in cols[c]))
        for i, c in enumerate(order):
            dx = -1 if i == 0 else 1
            for (y, x) in cols[c]:
                nx = x + dx
                if 0 <= nx < g.shape[1]:
                    out[y, nx] = c
            emit(out.copy(), f"Shift the {'upper' if dx < 0 else 'lower'} colour-{c} part one column {'left' if dx < 0 else 'right'}.")
    emit(out.copy(), "Final: every stacked pair has sheared apart, top left by 1 and bottom right by 1.")
    return out
